USE db_compras;
CREATE TABLE IF NOT EXISTS suppliers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(180) NOT NULL, phone VARCHAR(50), email VARCHAR(190), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, supplier_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','received') NOT NULL DEFAULT 'pending', created_by BIGINT UNSIGNED, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (supplier_id) REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS purchase_order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, quantity INT UNSIGNED NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, lot_number VARCHAR(100), expiry_date DATE, FOREIGN KEY (order_id) REFERENCES purchase_orders(id)) ENGINE=InnoDB;
